(4176903, 598829, 73601, '<td valign="top">simplicity is great and this is wonderful, perfect dof</td>', 'simplicity is great and this is wonderful, perfect dof', '2007-10-17 22:42:12.000000', NULL, 1),
(4176904, 600387, 23002, '<td valign="top">Great flower pic.  the petal definition on the left side is amazing.  great job not to overexpose this light subject.  it is unfortunate that the bug is minor part of the pic, but it is a nice photo without him in it.</td>', 'Great flower pic.  the petal definition on the left side is amazing.  great job not to overexpose this light subject.  it is unfortunate that the bug is minor part of the pic, but it is a nice photo without him in it.', '2007-10-17 22:42:43.000000', NULL, 1),
(4176908, 598753, 74406, '<td valign="top">cool!!!!!!!!</td>', 'cool!!!!!!!!', '2007-10-17 22:43:25.000000', NULL, 1),
(4176915, 600099, 23002, '<td valign="top">I am going to guess that this is a true macro shot of part of a penny?  As a non American I do not know that for sure, and likely a lot of others won''t either.  It is a shame because this is likely one of the few true macro shots in the competition.  Not really exciting but I will give you a 7 for the effort of a real macro shot.</td>', 'I am going to guess that this is a true macro shot of part of a penny?  As a non American I do not know that for sure, and likely a lot of others won''t either.  It is a shame because this is likely one of the few true macro shots in the competition.  Not really exciting but I will give you a 7 for the effort of a real macro shot.', '2007-10-17 22:45:41.000000', NULL, 1),
(4176921, 600021, 23002, '<td valign="top">Very powerful.  I love the glow from beneath.  It might be a bit better to not have the stem go right up the middle.  still nice though.</td>', 'Very powerful.  I love the glow from beneath.  It might be a bit better to not have the stem go right up the middle.  still nice though.', '2007-10-17 22:46:40.000000', NULL, 1),
(4176934, 600381, 23002, '<td valign="top">researching some blood tissue problems?  parasites?  ick.  good luck on your reading. :)</td>', 'researching some blood tissue problems?  parasites?  ick.  good luck on your reading. :)', '2007-10-17 22:50:00.000000', NULL, 1),
(4176940, 599250, 23002, '<td valign="top">very nice.  I love the fact that over half the photo is of water and that the boundry between the water and leaf is a nice pleasing shape.  great job on focus and dof as well.</td>', 'very nice.  I love the fact that over half the photo is of water and that the boundry between the water and leaf is a nice pleasing shape.  great job on focus and dof as well.', '2007-10-17 22:51:25.000000', NULL, 1),
(4176947, 600061, 23002, '<td valign="top">Looks like he has sucked the guts out of that one already!  as an arachnophobe  i find it tough to look at this let alone score it...but I will give it a 7 and  wish you a 4th place so it does not make the 1st page, which would force me to see it.  ick.   nice work, but ick.</td>', 'Looks like he has sucked the guts out of that one already!  as an arachnophobe  i find it tough to look at this let alone score it...but I will give it a 7 and  wish you a 4th place so it does not make the 1st page, which would force me to see it.  ick.   nice work, but ick.', '2007-10-17 22:54:25.000000', NULL, 1),
(4176950, 599159, 23002, '<td valign="top">great idea, shooting light through a salt shaker.  the concept gets an 8 from me.</td>', 'great idea, shooting light through a salt shaker.  the concept gets an 8 from me.', '2007-10-17 22:55:30.000000', NULL, 1),
(4176954, 600370, 23002, '<td valign="top">wow.  amazing shot.  the glow of the green of the mantis against the dark brown and reds really make him seem evil.  a 10, a fav, and see you on the front page.</td>', 'wow.  amazing shot.  the glow of the green of the mantis against the dark brown and reds really make him seem evil.  a 10, a fav, and see you on the front page.', '2007-10-17 22:56:35.000000', NULL, 1),
(4176960, 600087, 23002, '<td valign="top">It is a nice shot...but getting way overdone.  The shot itself would normally get a 7, but I am docking it 3 points because of it being so overdone.</td>', 'It is a nice shot...but getting way overdone.  The shot itself would normally get a 7, but I am docking it 3 points because of it being so overdone.', '2007-10-17 22:57:56.000000', NULL, 1),
(4176962, 600062, 23002, '<td valign="top">nice soft feel to it.  great pastel colour and focus is bang on. 8</td>', 'nice soft feel to it.  great pastel colour and focus is bang on. 8', '2007-10-17 22:58:22.000000', NULL, 1),
(4176970, 600129, 23002, '<td valign="top">OK, this just scared the crap out of me!  I am a severe arachnophobe.  It is a real macro, which gets extra points...but ugly as hell and scary. 7</td>', 'OK, this just scared the crap out of me!  I am a severe arachnophobe.  It is a real macro, which gets extra points...but ugly as hell and scary. 7', '2007-10-17 22:59:59.000000', NULL, 1),
(4176977, 600305, 23002, '<td valign="top">I know this was very hard to do, and I applaud your effort. However it is just sooooo overdone, all these water drop shots.  would have been a 9, now it is a 5.</td>', 'I know this was very hard to do, and I applaud your effort. However it is just sooooo overdone, all these water drop shots.  would have been a 9, now it is a 5.', '2007-10-17 23:01:26.000000', NULL, 1),
(4176981, 599314, 23002, '<td valign="top">It would be better if the focus was on the center of the rose instead of the outer part.</td>', 'It would be better if the focus was on the center of the rose instead of the outer part.', '2007-10-17 23:02:04.000000', NULL, 1),
(4176983, 598077, 23002, '<td valign="top">ribbit.</td>', 'ribbit.', '2007-10-17 23:02:16.000000', NULL, 1),
(4176990, 597542, 23002, '<td valign="top">Another amazing macro shot.  I have already "called" 2 others to make the front page....so I guess yours makes up the third I expect to see there.<br/> <br/>Great colour, background, focus... a standout. 10</td>', 'Another amazing macro shot.  I have already "called" 2 others to make the front page....so I guess yours makes up the third I expect to see there. Great colour, background, focus... a standout. 10', '2007-10-17 23:03:31.000000', NULL, 1);
