(4178246, 599937, 66348, '<td valign="top">Nice DOF. Love the color and composition. Very nicely done.</td>', 'Nice DOF. Love the color and composition. Very nicely done.', '2007-10-18 12:38:10.000000', NULL, 1),
(4178250, 600321, 66348, '<td valign="top">Very nice shot. Love the dark feel and the composition. Very nice how you filled the frame also. Nice work.</td>', 'Very nice shot. Love the dark feel and the composition. Very nice how you filled the frame also. Nice work.', '2007-10-18 12:39:49.000000', NULL, 1),
(4178252, 600062, 66348, '<td valign="top">Very nice color and composition. Really like how you filled the frame with this shot. Nice work.</td>', 'Very nice color and composition. Really like how you filled the frame with this shot. Nice work.', '2007-10-18 12:40:45.000000', NULL, 1),
(4178283, 600216, 66348, '<td valign="top">Very nice title. Really like the subject you chose to shoot. Composition is nice. Maybe a slight boost in contrast would have made the image stronger IMO. Great shot non the less. Nice work.</td>', 'Very nice title. Really like the subject you chose to shoot. Composition is nice. Maybe a slight boost in contrast would have made the image stronger IMO. Great shot non the less. Nice work.', '2007-10-18 12:51:49.000000', NULL, 1),
(4178286, 600251, 66348, '<td valign="top">I really like the textures of the mushroom. Nicely composed and well lit. Nice job.</td>', 'I really like the textures of the mushroom. Nicely composed and well lit. Nice job.', '2007-10-18 12:52:23.000000', NULL, 1),
(4178292, 600334, 66348, '<td valign="top">I remember playing with one of these when I was a kid, then my dad came and smacked me in the head and told me they were poisonous. I really like your composition here, and lighting. Seems as if the spider is walking on air to eat. Nicely done.</td>', 'I remember playing with one of these when I was a kid, then my dad came and smacked me in the head and told me they were poisonous. I really like your composition here, and lighting. Seems as if the spider is walking on air to eat. Nicely done.', '2007-10-18 12:53:29.000000', NULL, 1),
(4178296, 600390, 66348, '<td valign="top">I really enjoy the colors and composition. I like how it fills the frame. Nice choice of subject.</td>', 'I really enjoy the colors and composition. I like how it fills the frame. Nice choice of subject.', '2007-10-18 12:54:26.000000', NULL, 1),
(4178298, 599356, 66348, '<td valign="top">Very nicely done. I really like the DOF and bokeh look. Very good detail and just the right tone of color. Nice work.</td>', 'Very nicely done. I really like the DOF and bokeh look. Very good detail and just the right tone of color. Nice work.', '2007-10-18 12:55:10.000000', NULL, 1),
(4178299, 600196, 66348, '<td valign="top">Great close up. I like the tones and the sharpness and clarity are right on. Nice work.</td>', 'Great close up. I like the tones and the sharpness and clarity are right on. Nice work.', '2007-10-18 12:55:40.000000', NULL, 1),
(4178312, 599783, 66348, '<td valign="top">To be honest with you I kinda really like this shot. I had to come back to it, because at first I went through all the pics really quick but made a note to come back to this. I think a lot of people will pass it up and think gross, but I actually really like the texture and feel to this shot. It appears to be almost a NIN Cd cover. The sharpness and clarity are right on. I like the composition and the tones and contrast are right on. Your horizontal line is perfect and the title works. Very nicely done. 9</td>', 'To be honest with you I kinda really like this shot. I had to come back to it, because at first I went through all the pics really quick but made a note to come back to this. I think a lot of people will pass it up and think gross, but I actually really like the texture and feel to this shot. It appears to be almost a NIN Cd cover. The sharpness and clarity are right on. I like the composition and the tones and contrast are right on. Your horizontal line is perfect and the title works. Very nicely done. 9', '2007-10-18 13:00:06.000000', NULL, 1),
