(4182503, 599314, 67152, '<td valign="top">nice effort with this macro but the image just isn''t very sharp and the textures of the petals doesn''t really come across</td>', 'nice effort with this macro but the image just isn''t very sharp and the textures of the petals doesn''t really come across', '2007-10-20 07:16:06.000000', NULL, 1),
(4182512, 597164, 67152, '<td valign="top">the white balance seems to be off and the focus is not very well defined</td>', 'the white balance seems to be off and the focus is not very well defined', '2007-10-20 07:17:43.000000', NULL, 1),
(4182522, 600230, 67152, '<td valign="top">really nice detail on the back of the flower - but I almost think that the levels need to be a adjusted - it looks like it is significantly underexposed.  I would take a look at the histogram and bring down the white slider to really give this some punch</td>', 'really nice detail on the back of the flower - but I almost think that the levels need to be a adjusted - it looks like it is significantly underexposed.  I would take a look at the histogram and bring down the white slider to really give this some punch', '2007-10-20 07:26:19.000000', NULL, 1),
(4182526, 599638, 68887, '<td valign="top">too distracting the blurred area on the left, anyway good light and composition.</td>', 'too distracting the blurred area on the left, anyway good light and composition.', '2007-10-20 07:29:05.000000', NULL, 1);
