(4183046, 598753, 5112, '<td valign="top">My goodness, are some ants really that hairy?</td>', 'My goodness, are some ants really that hairy?', '2007-10-20 13:59:46.000000', NULL, 1),
(4183048, 598070, 5112, '<td valign="top">Good imaginations :)</td>', 'Good imaginations :)', '2007-10-20 14:00:19.000000', NULL, 1),
