(4186275, 597542, 52500, '<td valign="top">Congrats!  I had a feeling we were neck and neck.  Fantastic shot!</td>', 'Congrats!  I had a feeling we were neck and neck.  Fantastic shot!', '2007-10-22 01:06:44.000000', NULL, 0),
